import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"Codex — Motor de ejecución paralela","description":"OpenAI Codex como mi motor de tareas paralelas: sandboxes aisladas, refactors en abanico, tareas largas con diffs revisables.","frontmatter":{"title":"Codex — Motor de ejecución paralela","description":"OpenAI Codex como mi motor de tareas paralelas: sandboxes aisladas, refactors en abanico, tareas largas con diffs revisables."},"headers":[],"relativePath":"es/agentic/codex/index.md","filePath":"es/agentic/codex/index.md"}`),a={name:`es/agentic/codex/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="codex-—-motor-de-ejecucion-paralela" tabindex="-1">Codex — Motor de ejecución paralela <a class="header-anchor" href="#codex-—-motor-de-ejecucion-paralela" aria-label="Permalink to “Codex — Motor de ejecución paralela”">​</a></h1><p><strong>Codex</strong> es donde mi trabajo se abanica. El agente de OpenAI corre tareas en <strong>sandboxes aisladas</strong> — cada una con su propia copia del repositorio — lo que lo hace la herramienta correcta siempre que un cambio se descompone en piezas independientes: subir dependencias en varios paquetes, aplicar un refactor mecánico a cuarenta archivos, o generar variantes de una feature para comparar.</p><h2 id="el-patron-abanico" tabindex="-1">El patrón abanico <a class="header-anchor" href="#el-patron-abanico" aria-label="Permalink to “El patrón abanico”">​</a></h2><ol><li>Descompón la tarea en piezas que no puedan chocar — una sandbox por pieza.</li><li>Escribe el brief para que cada pieza tenga criterios de aceptación idénticos.</li><li>Déjalas correr en paralelo; recolecta los diffs.</li><li>Revisa como un maestro de merges: acepta, rechaza, o devuelve con un brief más afilado.</li></ol><p>La disciplina que hace esto seguro es la misma que en cualquier sistema paralelo: <strong>aísla lo que puede chocar, secuencia lo que no.</strong> Dos agentes editando el mismo módulo no es paralelismo; es un conflicto de merge con pasos extra. Por eso mis briefs declaran explícitamente los límites de archivos.</p><h2 id="donde-codex-le-gana-a-todo" tabindex="-1">Dónde Codex le gana a todo <a class="header-anchor" href="#donde-codex-le-gana-a-todo" aria-label="Permalink to “Dónde Codex le gana a todo”">​</a></h2><ul><li><strong>Escala mecánica.</strong> &quot;Renombra X a Y en todas partes y arregla los imports&quot; — tortura para un humano, trivial para una granja de sandboxes.</li><li><strong>Generación de opciones.</strong> Tres implementaciones de una función, comparadas lado a lado, superan al atormentarse por una.</li><li><strong>Paciencia de fondo.</strong> Instalaciones largas, suites de tests enormes, generación de datasets — tareas que no quiero babysitear.</li></ul><div class="tip custom-block"><p class="custom-block-title">Combinado con el resto</p><p>Codex produce las piezas; <a href="/Usf/es/agentic/claude-code/">Claude Code</a> las integra; <a href="/Usf/es/agentic/hermes/">Hermes</a> mantiene a la flota alimentada con modelos vía <a href="/Usf/es/projects/omnirouter/">OmniRouter</a>.</p></div>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};